CREATE SCHEMA IF NOT EXISTS private; REVOKE ALL ON SCHEMA private FROM PUBLIC,anon; GRANT USAGE ON SCHEMA private TO authenticated,service_role; ALTER FUNCTION public.account_access_allowed() SET SCHEMA private; CREATE POLICY "Private restriction records" ON public.account_restrictions FOR ALL TO authenticated USING(false) WITH CHECK(false); CREATE POLICY "Private blocked identifiers" ON public.security_blocks FOR ALL TO authenticated USING(false) WITH CHECK(false);